import { useId, useMemo } from "react";
import {
  Ban,
  Building2,
  Check,
  Clock,
  ContactRound,
  Layers,
  LayoutDashboard,
  Map as MapIcon,
  PencilRuler,
  TriangleAlert,
  User,
  Wrench,
} from "lucide-react";

// The starter layout is generated by the SAME function buildProfile
// emits it from, so a floor the buyer has not laid out yet is previewed
// as the floor the seeder will actually create — not a mock-up of one.
import { demoLayoutFor } from "../lib/profile.js";

/**
 * Preview — a live miniature of the system the buyer is configuring.
 *
 * This is the portal's whole argument. A buyer is not shopping for a
 * form; they are shopping for a system that is *theirs*, and the only
 * convincing way to say so is to show it to them while they type.
 *
 * Three rules keep it honest:
 *
 *   1. It renders from the provisioning profile — the same object that
 *      is handed to the seeder — so what they see here is what the
 *      seeder will build. Nothing is invented for the picture.
 *   2. It is a picture of an app, not an app. Nothing inside is
 *      focusable or clickable, there is no fetching, and there is no
 *      state: every pixel is derived from props on every render, so a
 *      keystroke in the builder is on screen in the same frame.
 *   3. It is scoped. The buyer's palette is written onto the wrapping
 *      element only, so it colours the preview and never bleeds into the
 *      vendor's own chrome around it.
 *
 * It deliberately does NOT reuse the buyer app's SpaceMap. That renderer
 * carries pan, zoom, pointer capture, selection and socket-fed status —
 * all of which are wrong for a thumbnail, and none of which the portal
 * should take a dependency on. This is a much simpler drawing that
 * borrows only SpaceMap's visual language: grid lines, dashed zones,
 * rounded piece bodies, and per-unit chips carrying colour AND icon.
 */

/* ─────────────────────── Theme resolution ─────────────────────── */

/**
 * The product's neutral palette, in the "R G B" channel form the tokens
 * use. Mirrors the :root defaults in the buyer app's index.css.
 *
 * These exist so the preview renders a complete, plausible system from
 * the very first keystroke — a buyer who has picked an accent but not
 * yet touched surfaces still sees a finished product rather than a
 * half-painted one. They are the ONLY colour values in this file, and
 * they are fallbacks, never a component's choice.
 */
const DEFAULT_CHANNELS = {
  accent: "34 211 238",
  "accent-ink": "4 34 43",
  "bg-page": "10 15 20",
  "bg-page-end": "15 22 30",
  "bg-card": "17 24 32",
  "bg-panel": "23 32 43",
  line: "236 241 246",
  "ink-primary": "236 241 246",
  "ink-secondary": "154 168 181",
  "ink-muted": "106 120 133",
  "state-available": "52 211 153",
  "state-reserved": "251 146 60",
  "state-occupied": "100 116 139",
  "state-unavailable": "248 113 113",
  "state-overstay": "192 132 252",
};

/** Maps a branding path in the profile to the token it drives. */
const TOKEN_MAP = [
  ["primaryColor", "accent"],
  ["accentTextColor", "accent-ink"],
  ["surface.page", "bg-page"],
  ["surface.pageEnd", "bg-page-end"],
  ["surface.card", "bg-card"],
  ["surface.panel", "bg-panel"],
  ["surface.line", "line"],
  ["ink.primary", "ink-primary"],
  ["ink.secondary", "ink-secondary"],
  ["ink.muted", "ink-muted"],
  ["states.available", "state-available"],
  ["states.reserved", "state-reserved"],
  ["states.occupied", "state-occupied"],
  ["states.unavailable", "state-unavailable"],
  ["states.overstay", "state-overstay"],
];

const read = (obj, path) => path.split(".").reduce((acc, key) => acc?.[key], obj);

/**
 * Converts a colour from the profile into "R G B" channels. Accepts the
 * #RRGGBB the contract specifies plus the shorthand and rgb() forms a
 * colour input or a pasted brand guide might produce.
 *
 * Returns null on anything unparseable rather than throwing: the buyer
 * is typing into these fields, so "#2D" is a normal intermediate state
 * and must fall back to the default instead of blanking the preview.
 *
 * Kept local rather than imported so this component renders correctly
 * on its own; it matches toRgbChannels in the buyer app's theme layer.
 */
function toChannels(value) {
  if (typeof value !== "string") return null;
  const input = value.trim();
  if (!input) return null;

  if (/^\d{1,3}(\s+\d{1,3}){2}$/.test(input)) return input;

  const hex = input.replace(/^#/, "");
  if (/^[0-9a-f]{3}$/i.test(hex)) {
    return [...hex].map((c) => parseInt(c + c, 16)).join(" ");
  }
  if (/^[0-9a-f]{6}([0-9a-f]{2})?$/i.test(hex)) {
    return [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16)).join(" ");
  }

  const fn = input.match(/^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)/i);
  if (fn) return fn.slice(1, 4).map((n) => Math.round(+n)).join(" ");

  return null;
}

/**
 * Builds the inline custom properties that re-skin the preview scope.
 *
 * Both halves of every token are written, not just the channels. A
 * custom property's var() references are substituted where the property
 * is DECLARED, not where it is used — so the --color-* forms declared at
 * :root have already resolved against the portal's own --c-* values by
 * the time they reach here. Re-declaring the channels alone would leave
 * every inline style and SVG fill still painting in the portal's colours.
 */
function themeVars(branding) {
  const vars = {};
  const channels = {};

  for (const [path, token] of TOKEN_MAP) {
    const value = toChannels(read(branding, path)) || DEFAULT_CHANNELS[token];
    channels[token] = value;
    vars[`--c-${token}`] = value;
    vars[`--color-${token}`] = `rgb(${value})`;
  }

  // Map chrome is derived from the line colour at the same alphas the
  // buyer app uses, so the grid and zones read identically here.
  const line = channels.line;
  vars["--color-map-grid"] = `rgb(${line} / 0.07)`;
  vars["--color-map-outline"] = `rgb(${line} / 0.16)`;
  vars["--color-map-piece-fill"] = `rgb(${line} / 0.05)`;
  vars["--color-map-piece-stroke"] = `rgb(${line} / 0.14)`;
  vars["--color-map-zone-fill"] = `rgb(${line} / 0.035)`;
  vars["--color-map-zone-stroke"] = `rgb(${line} / 0.2)`;

  return { vars, channels };
}

/**
 * Picks a legible foreground for a state colour, by relative luminance
 * rather than a brightness average so mid-tone greens and oranges land
 * on the right side of the threshold.
 *
 * Duplicated from the buyer app's readableInkFor on purpose: if the two
 * ever disagree, the preview would promise contrast the real product
 * does not deliver. Change them together.
 */
function readableInk(channels) {
  const [r, g, b] = channels.split(/\s+/).map(Number);
  const linear = (c) => {
    const s = c / 255;
    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
  };
  const luminance = 0.2126 * linear(r) + 0.7152 * linear(g) + 0.0722 * linear(b);

  if (luminance > 0.45) {
    return `rgb(${Math.round(r * 0.18)} ${Math.round(g * 0.18)} ${Math.round(b * 0.18)})`;
  }
  return `rgb(${Math.round(r + (255 - r) * 0.88)} ${Math.round(g + (255 - g) * 0.88)} ${Math.round(b + (255 - b) * 0.88)})`;
}

/* ────────────────────────── State meta ─────────────────────────── */

/**
 * Labels and icons only — colour arrives from the buyer's palette.
 * Every state is shown by colour AND icon, never colour alone.
 */
const STATE_META = {
  available: { label: "Available", Icon: Check },
  reserved: { label: "Reserved", Icon: Clock },
  occupied: { label: "Occupied", Icon: User },
  unavailable: { label: "Unavailable", Icon: Ban },
  overstay: { label: "Overstay", Icon: TriangleAlert },
};

/** The four availability states, in the order the legend reads them. */
const STATUS_ORDER = ["available", "reserved", "occupied", "unavailable"];

/** Out of service is a service status, not an availability one. */
const SERVICE_META = { label: "Out of service", Icon: Wrench };

/* ──────────────────────── Layout geometry ──────────────────────── */

const CELL = 24; // SVG units per grid cell — a third of the real renderer's
const PAD = 0.5; // half a cell of breathing room, tighter than the real map
const PIECE_INSET = 3;
const UNIT_GAP = 1.5;

/**
 * Lays a piece's units out inside its footprint, choosing the split that
 * makes the chips closest to square.
 *
 * The naive "one row of chips" split is wrong for exactly the pieces a
 * buyer is most proud of: an 8-seat boardroom on a 4x2 footprint becomes
 * eight unreadable slivers instead of a 4x2 grid. The preview has to
 * survive whatever catalog the buyer builds, not just one vertical's.
 */
function unitRects(footprint, count) {
  if (count < 1) return [];

  const bodyW = footprint.w * CELL - PIECE_INSET * 2;
  const bodyH = footprint.h * CELL - PIECE_INSET * 2;

  let best = { cols: count, rows: 1, score: Infinity };
  for (let cols = 1; cols <= count; cols += 1) {
    const rows = Math.ceil(count / cols);
    const w = (bodyW - UNIT_GAP * (cols - 1)) / cols;
    const h = (bodyH - UNIT_GAP * (rows - 1)) / rows;
    if (w <= 0 || h <= 0) continue;
    const score = Math.max(w / h, h / w);
    if (score < best.score) best = { cols, rows, score };
  }

  const { cols, rows } = best;
  const w = Math.max(1, (bodyW - UNIT_GAP * (cols - 1)) / cols);
  const h = Math.max(1, (bodyH - UNIT_GAP * (rows - 1)) / rows);

  return Array.from({ length: count }, (_, i) => ({
    x: PIECE_INSET + (i % cols) * (w + UNIT_GAP),
    y: PIECE_INSET + Math.floor(i / cols) * (h + UNIT_GAP),
    w,
    h,
  }));
}

/* ─────────────────────── Model from profile ────────────────────── */

/** Shown when there is no floor to draw yet — a plausible empty room. */
const DEFAULT_GRID = { cols: 12, rows: 8 };

/**
 * Grid and footprint are read from both shapes on purpose.
 *
 * The wizard holds them flat (`cols`/`rows`, `w`/`h`) while the emitted
 * profile nests them (`grid`, `footprint`), and this component is pointed
 * at wizard state on every keystroke and at the finished profile on the
 * review step. Reading only the nested form silently drew every floor at
 * the default size and every piece one cell square.
 */
function gridOf(floor) {
  const cols = Math.round(Number(floor?.grid?.cols ?? floor?.cols));
  const rows = Math.round(Number(floor?.grid?.rows ?? floor?.rows));
  return cols > 0 && rows > 0 ? { cols, rows } : DEFAULT_GRID;
}

function footprintOf(type) {
  const w = Math.round(Number(type?.footprint?.w ?? type?.w));
  const h = Math.round(Number(type?.footprint?.h ?? type?.h));
  return { w: w > 0 ? w : 1, h: h > 0 ? h : 1 };
}

/**
 * Resolves a placed resource's units.
 *
 * A piece the buyer has only just dropped onto a floor carries no unit
 * statuses yet, so its capacity comes from the catalog type and reads as
 * available. Showing it as empty space instead would make the preview
 * lag a click behind the editor, which is the one thing it must not do.
 */
function unitsOf(resource, type) {
  const raw = resource?.units;
  if (Array.isArray(raw) && raw.length) {
    return raw.map((u) => (typeof u === "string" ? u : u?.status || "available"));
  }
  const count = Number.isFinite(raw) ? raw : type?.seatCount;
  return Array.from({ length: Math.max(1, count || 1) }, () => "available");
}

/**
 * Flattens the chosen floor into everything the drawing and the summary
 * need, in one pass.
 */
function useFloorModel(config, floorIndex) {
  return useMemo(() => {
    const floors = Array.isArray(config?.floors) ? config.floors : [];
    const ordered = [...floors].sort((a, b) => (a?.order ?? 0) - (b?.order ?? 0));
    const floor = ordered[Math.min(Math.max(floorIndex, 0), ordered.length - 1)] || null;

    const activeIndex = floor ? ordered.indexOf(floor) : -1;

    const catalog = Array.isArray(config?.catalog) ? config.catalog : [];
    const typeByKey = new Map(catalog.map((t) => [t.key, t]));

    const grid = gridOf(floor);

    // A floor that already carries a resources array — even an empty one —
    // is taken at its word; only a floor with no layout at all borrows the
    // generated one, and only while the buyer has demo layout switched on.
    const layout =
      floor && !Array.isArray(floor.resources) && config?.demoLayout !== false
        ? demoLayoutFor(grid, catalog)
        : { zones: floor?.zones || [], labels: floor?.labels || [], resources: floor?.resources || [] };

    const counts = Object.fromEntries(STATUS_ORDER.map((s) => [s, 0]));
    let total = 0;
    let overstays = 0;
    let outOfService = 0;

    const pieces = layout.resources.flatMap((resource, index) => {
      const type = typeByKey.get(resource?.type ?? resource?.resourceType);
      // A piece whose catalog type the buyer has since deleted is simply
      // not drawn — mid-edit inconsistency should not be a crash.
      if (!type) return [];

      const footprint = footprintOf(type);
      const broken = resource.serviceStatus === "out_of_service";
      const overstayUnits = new Set(resource.overstayUnits || []);

      const units = unitsOf(resource, type).map((status, unitIndex) => {
        const key = STATE_META[status] && status !== "overstay" ? status : "unavailable";
        total += 1;
        counts[key] += 1;
        if (broken) outOfService += 1;
        if (overstayUnits.has(unitIndex)) overstays += 1;
        return { status: key, overstay: overstayUnits.has(unitIndex), broken };
      });

      return [{
        id: `${type.key}-${index}`,
        col: resource.position?.col ?? 0,
        row: resource.position?.row ?? 0,
        footprint,
        units,
        rects: unitRects(footprint, units.length),
      }];
    });

    return {
      floors: ordered,
      // The identity of `floor` is not reused for the active-pill check —
      // this is a new object — so the index is carried alongside it.
      floor: floor && { ...floor, grid, zones: layout.zones, labels: layout.labels },
      activeIndex,
      pieces,
      summary: { counts, total, overstays, outOfService },
    };
  }, [config, floorIndex]);
}

/* ────────────────────────── The mini map ───────────────────────── */

function MiniMap({ floor, pieces, palette, emptyHint }) {
  const gridId = useId();
  const grid = floor?.grid || DEFAULT_GRID;

  const view = {
    x: -PAD * CELL,
    y: -PAD * CELL,
    w: (grid.cols + PAD * 2) * CELL,
    h: (grid.rows + PAD * 2) * CELL,
  };

  return (
    <div
      className="relative w-full"
      style={{ aspectRatio: `${grid.cols + PAD * 2} / ${grid.rows + PAD * 2}`, maxHeight: 300 }}
    >
      <svg
        viewBox={`${view.x} ${view.y} ${view.w} ${view.h}`}
        preserveAspectRatio="xMidYMid meet"
        className="w-full h-full"
        role="img"
        aria-label={
          floor
            ? `Preview of ${floor.name}: ${pieces.length} pieces on a ${grid.cols} by ${grid.rows} grid`
            : "Preview of an empty floor"
        }
      >
        <defs>
          <pattern id={gridId} width={CELL} height={CELL} patternUnits="userSpaceOnUse">
            <path
              d={`M ${CELL} 0 L 0 0 0 ${CELL}`}
              fill="none"
              style={{ stroke: "var(--color-map-grid)" }}
              strokeWidth="1"
            />
          </pattern>
        </defs>

        <rect x="0" y="0" width={grid.cols * CELL} height={grid.rows * CELL} fill={`url(#${gridId})`} />
        <rect
          x="0"
          y="0"
          width={grid.cols * CELL}
          height={grid.rows * CELL}
          fill="none"
          style={{ stroke: "var(--color-map-outline)" }}
          strokeWidth="1"
          rx="3"
        />

        {/* ---- Zones: a named backdrop, membership derived from position ---- */}
        {(floor?.zones || []).filter((zone) => zone?.bounds).map((zone, i) => (
          <g key={`zone-${i}`}>
            <rect
              x={zone.bounds.col * CELL}
              y={zone.bounds.row * CELL}
              width={zone.bounds.w * CELL}
              height={zone.bounds.h * CELL}
              style={{ fill: "var(--color-map-zone-fill)", stroke: "var(--color-map-zone-stroke)" }}
              strokeWidth="1"
              strokeDasharray="4 3"
              rx="5"
            />
            <text
              x={zone.bounds.col * CELL + 5}
              y={zone.bounds.row * CELL + 11}
              style={{ fill: "var(--color-ink-muted)", textTransform: "uppercase" }}
              fontSize="7"
              fontWeight="600"
              letterSpacing="0.8"
            >
              {zone.name}
            </text>
          </g>
        ))}

        {/* ---- Pieces: the furniture, then its reservable units ---- */}
        {pieces.map((piece) => {
          const x = piece.col * CELL;
          const y = piece.row * CELL;
          return (
            <g key={piece.id}>
              <rect
                x={x + 1}
                y={y + 1}
                width={piece.footprint.w * CELL - 2}
                height={piece.footprint.h * CELL - 2}
                style={{ fill: "var(--color-map-piece-fill)", stroke: "var(--color-map-piece-stroke)" }}
                strokeWidth="0.75"
                rx="4"
              />
              {piece.units.map((unit, unitIndex) => {
                const r = piece.rects[unitIndex];
                if (!r) return null;

                // Overstay outranks the base status, and out-of-service
                // borrows the unavailable tone but keeps its own icon so
                // a broken unit stays distinguishable from a closed one.
                const toneKey = unit.overstay ? "overstay" : unit.broken ? "unavailable" : unit.status;
                const tone = palette[toneKey];
                const Icon = unit.overstay
                  ? STATE_META.overstay.Icon
                  : unit.broken
                    ? SERVICE_META.Icon
                    : STATE_META[unit.status].Icon;

                const size = Math.min(r.w, r.h);
                const iconSize = Math.min(Math.max(size * 0.52, 6), 11);

                return (
                  <g key={unitIndex}>
                    <rect
                      x={x + r.x}
                      y={y + r.y}
                      width={r.w}
                      height={r.h}
                      rx="2.5"
                      style={{
                        fill: tone.color,
                        stroke: "rgb(var(--c-bg-page) / 0.45)",
                        strokeWidth: 0.75,
                        // A recolour mid-configuration should read as the
                        // same seat changing, not as the map redrawing.
                        transition: "fill var(--dur-base, 240ms) var(--ease-out, ease)",
                      }}
                    />
                    {size >= 9 && (
                      <Icon
                        x={x + r.x + r.w / 2 - iconSize / 2}
                        y={y + r.y + r.h / 2 - iconSize / 2}
                        width={iconSize}
                        height={iconSize}
                        color={tone.ink}
                        strokeWidth={2.5}
                      />
                    )}
                  </g>
                );
              })}
            </g>
          );
        })}

        {/* ---- Labels: free orientation text, not reservable ---- */}
        {(floor?.labels || []).filter((label) => label?.position).map((label, i) => (
          <text
            key={`label-${i}`}
            x={label.position.col * CELL + CELL / 2}
            y={label.position.row * CELL + CELL / 2 + 2.5}
            textAnchor="middle"
            fontSize="7"
            fontWeight="500"
            style={{ fill: "var(--color-ink-secondary)" }}
          >
            {label.text}
          </text>
        ))}
      </svg>

      {emptyHint && (
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <span
            className="text-[10px] px-2.5 py-1 rounded-md border border-dashed"
            style={{ color: "var(--color-ink-muted)", borderColor: "rgb(var(--c-line) / 0.2)" }}
          >
            {emptyHint}
          </span>
        </div>
      )}
    </div>
  );
}

/* ─────────────────────────── The preview ───────────────────────── */

const NAV = [
  { label: "Map", Icon: MapIcon },
  { label: "Console", Icon: LayoutDashboard },
  { label: "Editor", Icon: PencilRuler },
  { label: "Kiosk", Icon: ContactRound },
];

/** Coloured swatch + label. Colour alone never carries a meaning. */
function LegendItem({ tone, label, count }) {
  return (
    <span className="inline-flex items-center gap-1" style={{ color: "var(--color-ink-secondary)" }}>
      <span
        className="w-2 h-2 rounded-[2px] shrink-0"
        style={{ background: `var(--color-state-${tone})` }}
      />
      {label}
      {count !== undefined && (
        <span className="font-semibold tabular-nums" style={{ color: "var(--color-ink-primary)" }}>
          {count}
        </span>
      )}
    </span>
  );
}

export default function Preview({ config, floorIndex = 0, className = "" }) {
  const { vars, channels } = useMemo(() => themeVars(config?.branding), [config?.branding]);

  // Concrete values, not var() references: the icon colour lands on an
  // SVG presentation attribute, which does not resolve custom properties.
  const palette = useMemo(
    () =>
      Object.fromEntries(
        Object.keys(STATE_META).map((key) => {
          const ch = channels[`state-${key}`];
          return [key, { color: `rgb(${ch})`, ink: readableInk(ch) }];
        })
      ),
    [channels]
  );

  const { floors, floor, activeIndex, pieces, summary } = useFloorModel(config, floorIndex);

  // Terminology is always the buyer's, and the fallbacks stay
  // vertical-neutral — a default of "seat" would quietly make every
  // unconfigured preview a library.
  const resourceNoun = config?.terminology?.resourceNoun?.trim() || "resource";
  const memberNoun = config?.terminology?.memberNoun?.trim() || "member";
  const orgName = config?.organizationName?.trim() || "Your organization";
  const siteName = config?.siteName?.trim() || "Main site";

  const emptyHint = !floor
    ? "Add a floor to see it here"
    : pieces.length === 0
      ? "Place pieces from the catalog"
      : null;

  return (
    // The buyer's palette is written here and nowhere else, so it colours
    // this subtree and leaves the portal's own chrome alone.
    <div
      className={`silla-preview overflow-hidden rounded-lg ${className}`}
      style={{
        ...vars,
        background: "linear-gradient(180deg, var(--color-bg-page), var(--color-bg-page-end))",
        color: "var(--color-ink-primary)",
      }}
      // A picture of an application: nothing inside is a real control, so
      // nothing is focusable and the whole thing announces once.
      role="group"
      aria-label={`Preview of ${orgName}`}
    >
      {/* ---- Header ---- */}
      <div
        className="h-9 px-2.5 flex items-center gap-1.5 border-b"
        style={{ borderColor: "rgb(var(--c-line) / 0.1)", background: "rgb(var(--c-bg-page) / 0.8)" }}
      >
        <span
          className="w-5 h-5 rounded shrink-0 flex items-center justify-center"
          style={{ background: "var(--color-accent)", color: "var(--color-accent-ink)" }}
        >
          <Building2 size={12} />
        </span>
        <span className="text-[11px] font-semibold truncate max-w-[10rem] mr-1.5">{orgName}</span>

        <nav className="flex items-center gap-0.5 mr-auto" aria-hidden="true">
          {NAV.map(({ label, Icon }, i) => (
            <span
              key={label}
              className="h-6 px-1.5 rounded text-[10px] flex items-center gap-1 whitespace-nowrap"
              style={
                i === 0
                  ? { background: "var(--color-bg-panel)", color: "var(--color-ink-primary)" }
                  : { color: "var(--color-ink-secondary)" }
              }
            >
              <Icon size={11} />
              <span className="hidden sm:inline">{label}</span>
            </span>
          ))}
        </nav>

        <span
          className="px-1.5 py-0.5 rounded text-[9px] font-medium capitalize shrink-0"
          style={{ background: "rgb(var(--c-accent) / 0.15)", color: "var(--color-accent)" }}
        >
          {memberNoun}
        </span>
      </div>

      <div className="p-3">
        {/* ---- Floor switcher ---- */}
        <div className="flex items-center gap-1.5 mb-2.5 flex-wrap">
          <Layers size={12} style={{ color: "var(--color-ink-muted)" }} />
          {floors.length > 0 ? (
            <span
              className="inline-flex flex-wrap gap-0.5 p-0.5 rounded-md border"
              style={{ background: "rgb(var(--c-bg-panel) / 0.6)", borderColor: "rgb(var(--c-line) / 0.1)" }}
            >
              {floors.map((f, i) => (
                <span
                  key={`${f.name}-${i}`}
                  className="h-5 px-1.5 rounded text-[10px] font-medium flex items-center"
                  style={
                    i === activeIndex
                      ? { background: "var(--color-accent)", color: "var(--color-accent-ink)" }
                      : { color: "var(--color-ink-secondary)" }
                  }
                >
                  {f.name || `Floor ${i + 1}`}
                </span>
              ))}
            </span>
          ) : (
            <span className="text-[10px]" style={{ color: "var(--color-ink-muted)" }}>
              No floors yet
            </span>
          )}
          <span className="text-[10px] ml-auto truncate" style={{ color: "var(--color-ink-muted)" }}>
            {siteName}
          </span>
        </div>

        {/* ---- Occupancy summary, in the buyer's own noun ---- */}
        <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mb-2 text-[10px]">
          <span style={{ color: "var(--color-ink-secondary)" }}>
            <span className="font-semibold tabular-nums" style={{ color: "var(--color-ink-primary)" }}>
              {summary.counts.available}
            </span>{" "}
            of <span className="tabular-nums">{summary.total}</span>{" "}
            {summary.total === 1 ? resourceNoun : `${resourceNoun}s`} open
          </span>
          <span className="w-px h-3" style={{ background: "rgb(var(--c-line) / 0.12)" }} />
          {/* Overstay is an overlay on top of a status rather than one of
              the four, so it is listed but only ever counted when live. */}
          {STATUS_ORDER.map((key) => (
            <LegendItem key={key} tone={key} label={STATE_META[key].label} count={summary.counts[key]} />
          ))}
          <LegendItem
            tone="overstay"
            label={STATE_META.overstay.label}
            count={summary.overstays || undefined}
          />
          {summary.outOfService > 0 && (
            <LegendItem tone="unavailable" label={SERVICE_META.label} count={summary.outOfService} />
          )}
        </div>

        {/* ---- The map ---- */}
        <div
          className="rounded-md border overflow-hidden p-1.5"
          style={{ background: "var(--color-bg-card)", borderColor: "rgb(var(--c-line) / 0.1)" }}
        >
          <MiniMap floor={floor} pieces={pieces} palette={palette} emptyHint={emptyHint} />
        </div>
      </div>
    </div>
  );
}

/* ────────────────────────── Framed variant ─────────────────────── */

/**
 * PreviewFrame — the same preview inside browser chrome, for the review
 * step. The frame is the VENDOR's furniture: it stays in the portal's
 * own tokens so the buyer reads the coloured part as their product and
 * the grey part as the window it will run in.
 */
export function PreviewFrame({ config, className = "", ...previewProps }) {
  const subdomain = config?.key?.trim() || "your-org";

  return (
    <div className={`rounded-lg border border-line/10 bg-bg-panel shadow-raised overflow-hidden ${className}`}>
      <div className="h-8 px-3 flex items-center gap-2 border-b border-line/10">
        {/* Neutral dots rather than the usual red/amber/green: a literal
            colour here would be the one thing on screen no deployment
            could re-skin, and it would compete with the state legend. */}
        <span className="flex gap-1" aria-hidden="true">
          {[0, 1, 2].map((i) => (
            <span key={i} className="w-2 h-2 rounded-full bg-line/20" />
          ))}
        </span>
        <span className="mx-auto px-2.5 py-0.5 rounded-full bg-bg-page/60 border border-line/10 text-[10px] text-ink-muted font-mono truncate max-w-[16rem]">
          {subdomain}.silla.app
        </span>
        {/* Matches the dots' width so the URL stays optically centred. */}
        <span className="w-8" aria-hidden="true" />
      </div>

      <div className="p-2">
        <Preview config={config} {...previewProps} />
      </div>
    </div>
  );
}
